-- ============================================================-- 030_chat_fk_profiles.sql — FK squadron_chat_messages.user_id → profiles.id-- ============================================================-- Добавляем FK чтобы Supabase мог резолвить profiles:user_id() в .select()ALTER TABLE public.squadron_chat_messages  DROP CONSTRAINT IF EXISTS fk_squadron_chat_messages_profiles;ALTER TABLE public.squadron_chat_messages  ADD CONSTRAINT fk_squadron_chat_messages_profiles  FOREIGN KEY (user_id) REFERENCES public.profiles(id)  ON DELETE CASCADE;